// MIRROR-1000 category specs (architect builder, 2026-11-11): what build.ts composes the 1,000 prompts from. Each base
// category has intents (frames, must_do, must_not, check) and constraints (each adds a must_do item and a check). Style
// categories (typos, long, multi_part) reuse base combinations nobody used; small_talk, ambiguity, multilingual and short are
// hand-written. Capabilities come from docs/architect/FEATURES.md (F01-F40) and the specs (MASS-APPLY, NETWORKING,
// TASK-INTELLIGENCE, RESPONSE-RULES section 2). Checks use the outcome.ts grammar. Slot names are vocab.ts kinds ({role},
// {city}, {company}, {person}, ...); a check may name a slot too.
export interface Setup { turns: string[]; state: Record<string, unknown> }
export interface Intent { key: string; frames: string[]; must_do: string[]; must_not: string[]; check: string; guards?: string[]; setup?: Setup; stop?: boolean; noMods?: string[] }
export interface Mod { key: string; group?: string; phrases: string[]; must: string; not?: string; check?: string; only?: string[] }
export interface Hand { prompt: string; must_do: string[]; must_not: string[]; check: string; setup?: Setup; persona?: string; stop?: boolean }
export interface Spec {
  cat: string; target: number; personas: string[]; guards: string[]; intents: Intent[]; mods: Mod[]; hand?: Hand[]; setup?: Setup; resume?: string;
  must_not?: string[]; stop?: boolean; from?: string[]; extra_must: string[]; context?: string[];
}
const r = String.raw;

// ------------------------------------------------------------------------------------------------ shared checks and words
const NOSUB = "no_claim(submitted)", NOSEND = "no_claim(sent)", ND = "not_declined";
const LISTED = r`min_items(1) || reply =~ /\b(no (verified |open |matching |current )?(roles|jobs|postings|matches|openings|results)|none (matched|found|are open|of them)|couldn'?t find|didn'?t find|found no|nothing (matched|came up|open))\b/i`;
const EMPTY = r`reply =~ /\b(no (verified |open |matching |current )?(roles|jobs|postings|matches|openings|internships|results)|none|couldn'?t find|didn'?t find|found no|nothing (matched|came up|open)|zero)\b/i`;
const DRAFTED = r`reply =~ /(subject:|^\s*(hi|hello|dear|hey)\b|\n\s*(hi|hello|dear|hey)\b|draft)/im`;
const NOT_INVENTED = "never states a fact about the person they did not give";
const PERSONAS = [
  "junior studying {major} at {school}, looking for {role} internships around {city}",
  "senior studying {major}, graduating {month} {year}, wants {level} {role} roles",
  "new grad with a {major} degree, open to relocating from {city}",
  "career switcher from teaching into {role} work, based in {city}",
  "mid-career {role} in {city} looking for a step up",
  "international student on a student visa studying {major} at {school}",
  "part-time student working retail in {city}, wants a {role} internship",
  "laid-off {role} with five years of experience, searching nationally",
  "veteran moving into {industry} operations roles near {city}",
  "PhD candidate in {major} exploring industry {role} jobs",
];

